import { Component } from '@angular/core';
import { TextareaFieldComponent } from '@conciso/design-system-angular';

@Component({
  selector: 'app-demo',
  imports: [TextareaFieldComponent],
  template: `
    <div style="display:flex;flex-direction:column;gap:var(--s3);max-width:28rem">
        <cds-textarea-field
            label="Nachricht"
            placeholder="Ihre Nachricht an uns"
            fieldId="form-message"
            [formControl]="ctrl">
        </cds-textarea-field>
        <p style="font:14px/1.4 system-ui,sans-serif;margin:0">
            Zeichen:
            <strong>{{ ctrl.value?.length || 0 }}</strong>
        </p>
    </div>`,
})
export class DemoComponent {}
